import math


def _linear_quantile(sorted_data, p):
    n = len(sorted_data)
    if n == 1:
        return float(sorted_data[0])
    pos = (n - 1) * p
    lo = int(math.floor(pos))
    hi = min(lo + 1, n - 1)
    frac = pos - lo
    return float(sorted_data[lo]) + (float(sorted_data[hi]) - float(sorted_data[lo])) * frac


def flattened_interquartile_range(nested):
    data = sorted(x for inner in nested for x in inner)
    if not data:
        raise ValueError("cannot compute interquartile range of empty data")
    q1 = _linear_quantile(data, 0.25)
    q3 = _linear_quantile(data, 0.75)
    return float(q3 - q1)

