import re
import math


def _words(text):
    return re.findall(r'\w+', text)


def paired_word_length_t_statistic(text1, text2):
    w1 = _words(text1)
    w2 = _words(text2)
    if len(w1) != len(w2):
        raise ValueError('texts have different numbers of words')
    n = len(w1)
    if n < 2:
        return float('nan')
    d = [len(a) - len(b) for a, b in zip(w1, w2)]
    mean = sum(d) / n
    var = sum((x - mean) ** 2 for x in d) / (n - 1)
    denom = math.sqrt(var / n)
    if denom == 0:
        if mean == 0:
            return float('nan')
        return math.copysign(float('inf'), mean)
    return float(mean / denom)

import math
from collections import Counter


def _gammainc_lower_series(a, x):
    # regularized lower incomplete gamma P(a, x) via series
    term = 1.0 / a
    total = term
    ap = a
    for _ in range(100000):
        ap += 1.0
        term *= x / ap
        total += term
        if abs(term) < abs(total) * 1e-17:
            break
    return total * math.exp(-x + a * math.log(x) - math.lgamma(a))


def _gammainc_upper_cf(a, x):
    # regularized upper incomplete gamma Q(a, x) via continued fraction (Lentz)
    tiny = 1e-300
    b = x + 1.0 - a
    c = 1.0 / tiny
    d = 1.0 / b
    h = d
    for i in range(1, 100000):
        an = -i * (i - a)
        b += 2.0
        d = an * d + b
        if abs(d) < tiny:
            d = tiny
        c = b + an / c
        if abs(c) < tiny:
            c = tiny
        d = 1.0 / d
        delta = d * c
        h *= delta
        if abs(delta - 1.0) < 1e-16:
            break
    return math.exp(-x + a * math.log(x) - math.lgamma(a)) * h


def _chi2_sf(x, df):
    if x <= 0:
        return 1.0
    if df == 1:
        return math.erfc(math.sqrt(x / 2.0))
    a = df / 2.0
    z = x / 2.0
    if z < a + 1.0:
        return max(0.0, 1.0 - _gammainc_lower_series(a, z))
    return _gammainc_upper_cf(a, z)


def chi_square_independence_pvalue(labels1, labels2):
    labels1 = list(labels1)
    labels2 = list(labels2)
    if len(labels1) != len(labels2):
        raise ValueError("label lists must have equal length")
    cats1 = sorted(set(labels1), key=repr)
    cats2 = sorted(set(labels2), key=repr)
    if len(cats1) < 2 or len(cats2) < 2:
        raise ValueError("each list needs at least two distinct categories")
    pairs = Counter(zip(labels1, labels2))
    table = [[pairs.get((r, c), 0) for c in cats2] for r in cats1]
    for row in table:
        for v in row:
            if v < 5:
                raise ValueError("every combination needs at least 5 observations")
    n = float(len(labels1))
    row_tot = [sum(row) for row in table]
    col_tot = [sum(table[i][j] for i in range(len(cats1))) for j in range(len(cats2))]
    df = (len(cats1) - 1) * (len(cats2) - 1)
    chi2 = 0.0
    for i in range(len(cats1)):
        for j in range(len(cats2)):
            e = row_tot[i] * col_tot[j] / n
            o = float(table[i][j])
            if df == 1:
                diff = e - o
                mag = min(0.5, abs(diff))
                if diff > 0:
                    o += mag
                elif diff < 0:
                    o -= mag
            chi2 += (o - e) ** 2 / e
    return float(_chi2_sf(chi2, df))

