import math
import numbers


def _to_fraction(v):
    if isinstance(v, bool) or not isinstance(v, numbers.Real):
        raise ValueError("all values must be real numbers")
    if isinstance(v, float) and not math.isfinite(v):
        raise ValueError("values must be finite")
    try:
        return Fraction(v)
    except (ValueError, OverflowError, TypeError):
        raise ValueError("invalid numeric value: %r" % (v,))


def _solve(a, b):
    n = len(a)
    m = [list(a[i]) + [b[i]] for i in range(n)]
    for col in range(n):
        piv = None
        for r in range(col, n):
            if m[r][col] != 0:
                piv = r
                break
        if piv is None:
            raise ValueError("predictors are linearly dependent or too few rows; regression is not identifiable")
        m[col], m[piv] = m[piv], m[col]
        pv = m[col][col]
        for r in range(n):
            if r != col and m[r][col] != 0:
                f = m[r][col] / pv
                rowr = m[r]
                rowc = m[col]
                for c in range(col, n + 1):
                    rowr[c] -= f * rowc[c]
    return [m[i][n] / m[i][i] for i in range(n)]


def fit_linear_regression(rows):
    if rows is None:
        raise ValueError("rows must not be empty")
    try:
        rows = list(rows)
    except TypeError:
        raise ValueError("rows must be a sequence of rows")
    if not rows:
        raise ValueError("rows must not be empty")
    data = []
    for row in rows:
        try:
            vals = list(row)
        except TypeError:
            raise ValueError("each row must be a sequence of five numbers")
        if len(vals) != 5:
            raise ValueError("each row must have exactly five values")
        data.append([_to_fraction(v) for v in vals])

    p = 5
    xtx = [[Fraction(0)] * p for _ in range(p)]
    xty = [Fraction(0)] * p
    for r in data:
        x = [Fraction(1)] + r[:4]
        y = r[4]
        for i in range(p):
            xi = x[i]
            xty[i] += xi * y
            row = xtx[i]
            for j in range(i, p):
                row[j] += xi * x[j]
    for i in range(p):
        for j in range(i):
            xtx[i][j] = xtx[j][i]

    beta = _solve(xtx, xty)

    n = len(data)
    ybar = sum(r[4] for r in data) / n
    sse = Fraction(0)
    sst = Fraction(0)
    for r in data:
        pred = beta[0] + sum(beta[k + 1] * r[k] for k in range(4))
        res = r[4] - pred
        sse += res * res
        d = r[4] - ybar
        sst += d * d
    if sst == 0:
        r2 = 1.0
    else:
        r2 = float(1 - sse / sst)
    return ([float(b) for b in beta], r2)

