import math
import numpy as np


def _clean(value, digits=12):
    v = round(float(value), digits)
    if v == 0:
        v = 0.0  # normalise -0.0
    return v


def fit_linear_regression(rows):
    if rows is None:
        raise ValueError("rows must be a non-empty list of rows")
    try:
        rows = list(rows)
    except TypeError:
        raise ValueError("rows must be a list of rows")
    if not rows:
        raise ValueError("rows must not be empty")

    data = []
    for i, row in enumerate(rows):
        if isinstance(row, (str, bytes)):
            raise ValueError(f"row {i} is not a sequence of numbers")
        try:
            values = list(row)
        except TypeError:
            raise ValueError(f"row {i} is not a sequence of numbers")
        if len(values) != 5:
            raise ValueError(f"row {i} must have exactly five values, got {len(values)}")
        converted = []
        for v in values:
            if isinstance(v, (str, bytes)):
                raise ValueError(f"row {i} contains a non-numeric value: {v!r}")
            try:
                f = float(v)
            except (TypeError, ValueError):
                raise ValueError(f"row {i} contains a non-numeric value: {v!r}")
            if not math.isfinite(f):
                raise ValueError(f"row {i} contains a non-finite value: {v!r}")
            converted.append(f)
        data.append(converted)

    arr = np.asarray(data, dtype=float)
    X = np.column_stack([np.ones(arr.shape[0]), arr[:, :4]])
    y = arr[:, 4]

    # Least squares (minimum-norm solution if the design is rank deficient)
    beta, _, _, _ = np.linalg.lstsq(X, y, rcond=None)

    fitted = X @ beta
    residuals = y - fitted
    ss_res = float(np.dot(residuals, residuals))
    y_mean = float(np.mean(y))
    centered = y - y_mean
    ss_tot = float(np.dot(centered, centered))

    scale = max(1.0, float(np.dot(y, y)))
    if ss_tot <= 1e-24 * scale:
        # Constant response: the intercept-only model fits it perfectly.
        r_squared = 1.0
    else:
        r_squared = 1.0 - ss_res / ss_tot

    coefficients = [_clean(b) for b in beta]
    return coefficients, _clean(r_squared)

