    span = hi - lo
    interior = [lo + span * k / bins for k in range(1, bins)]
    counts = [0] * bins
    for v in values:
        if v >= hi:
            idx = bins - 1
        else:
            idx = bisect_right(interior, v)
            if idx > bins - 1:
                idx = bins - 1
        counts[idx] += 1
    return counts

