import math


def _softplus(z):
    if z > 0:
        return z + math.log1p(math.exp(-z))
    return math.log1p(math.exp(z))


def _sigmoid(z):
    if z >= 0:
        e = math.exp(-z)
        return 1.0 / (1.0 + e)
    e = math.exp(z)
    return e / (1.0 + e)


def _objective(w, b, xs, ys, C):
    total = 0.5 * w * w
    for x, y in zip(xs, ys):
        z = w * x + b
        total += C * (_softplus(z) - y * z)
    return total


def _fit(xs, ys, C=1.0, max_iter=200, tol=1e-10):
    w, b = 0.0, 0.0
    f = _objective(w, b, xs, ys, C)
    for _ in range(max_iter):
        gw = w
        gb = 0.0
        hww = 1.0
        hwb = 0.0
        hbb = 0.0
        for x, y in zip(xs, ys):
            p = _sigmoid(w * x + b)
            r = p - y
            s = p * (1.0 - p)
            gw += C * r * x
            gb += C * r
            hww += C * s * x * x
            hwb += C * s * x
            hbb += C * s
        hbb += 1e-12
        det = hww * hbb - hwb * hwb
        if det <= 1e-18:
            dw, db = -gw, -gb
        else:
            dw = -(hbb * gw - hwb * gb) / det
            db = -(-hwb * gw + hww * gb) / det
        step = 1.0
        slope = gw * dw + gb * db
        improved = False
        for _ in range(60):
            nw, nb = w + step * dw, b + step * db
            nf = _objective(nw, nb, xs, ys, C)
            if nf <= f + 1e-4 * step * slope:
                improved = True
                break
            step *= 0.5
        if not improved:
            break
        change = abs(nw - w) + abs(nb - b)
        w, b = nw, nb
        fdiff = f - nf
        f = nf
        if change < tol or fdiff < 1e-14:
            break
    return w, b


def logistic_confusion_matrix(train_x, train_y, test_x, test_y):
