def _solve_linear(A, b):
    n = len(A)
    M = [list(map(float, A[i])) + [float(b[i])] for i in range(n)]
    scale = max([abs(v) for row in A for v in row] + [1.0])
    tol = 1e-12 * scale
    pivot_cols = []
    row = 0
    for col in range(n):
        if row >= n:
            break
        piv = max(range(row, n), key=lambda r: abs(M[r][col]))
        if abs(M[piv][col]) <= tol:
            continue
        M[row], M[piv] = M[piv], M[row]
        for r in range(n):
            if r != row and M[r][col] != 0.0:
                f = M[r][col] / M[row][col]
                for c in range(col, n + 1):
                    M[r][c] -= f * M[row][c]
        pivot_cols.append((row, col))
        row += 1
    x = [0.0] * n
    for r, c in pivot_cols:
        x[c] = M[r][n] / M[r][c]
    return x


def forecast_closing_prices(prices, p, steps):
    prices = [float(v) for v in prices]
    p = int(p)
    steps = int(steps)
    if p < 0:
        raise ValueError("p must be non-negative")
    if steps <= 0:
        return []
    if not prices:
        raise ValueError("prices must not be empty")
    diffs = [prices[i] - prices[i - 1] for i in range(1, len(prices))]
    if p == 0:
        return [prices[-1] for _ in range(steps)]
    if len(diffs) <= p:
        raise ValueError("not enough data to fit AR(p) on differences")
    XtX = [[0.0] * p for _ in range(p)]
    Xty = [0.0] * p
    for t in range(p, len(diffs)):
        y = diffs[t]
        x = [diffs[t - 1 - j] for j in range(p)]
        for i in range(p):
            Xty[i] += x[i] * y
            for j in range(p):
                XtX[i][j] += x[i] * x[j]
    phi = _solve_linear(XtX, Xty)
    hist = list(diffs)
    last = prices[-1]
    out = []
    for _ in range(steps):
        d = 0.0
        for j in range(p):
            d += phi[j] * hist[-1 - j]
        hist.append(d)
        last = last + d
        out.append(float(last))
    return out

