from math import isqrt


def _corr(xs, ys):
    n = len(xs)
    if n == 0:
        return float('nan')
    mx = sum(xs, Fraction(0)) / n
    my = sum(ys, Fraction(0)) / n
    sxy = Fraction(0)
    sxx = Fraction(0)
    syy = Fraction(0)
    for x, y in zip(xs, ys):
        dx = x - mx
        dy = y - my
        sxy += dx * dy
        sxx += dx * dx
        syy += dy * dy
    if sxx == 0 or syy == 0:
        return float('nan')
    if sxy == 0:
        return 0.0
    r2 = (sxy * sxy) / (sxx * syy)
    p, q = r2.numerator, r2.denominator
    k = max(0, 160 + (q.bit_length() - p.bit_length()) // 2 + 1)
    root = isqrt((p << (2 * k)) // q)
    val = float(Fraction(root, 1 << k))
    if val > 1.0:
        val = 1.0
    return val if sxy > 0 else -val


